    return (i + 1) + ') [' + x.prioridade + ' ' + x.score + '] ' + x.acao + ' — ' + x.motivo;
});
node.status({ fill: 'green', shape: 'dot', text: r.pet.nome + ': ' + r.totalRecomendacoes + ' recomendação(ões)' });
var mqttMsg = { topic: 'clyvocare/ia/recomendacoes', payload: {
    pet: r.pet, abordagemIA: r.abordagemIA, totalRecomendacoes: r.totalRecomendacoes,
    recomendacoes: (r.recomendacoes || []).map(function (x) { return { regra: x.regra, servico: x.servico, acao: x.acao, score: x.score, prioridade: x.prioridade, motivo: x.motivo }; }),
    geradoEm: r.geradoEm, aviso: r.aviso, origem: 'api-clyvocare-sprint4' } };
var dbg = { payload: { resumo: r.resumo || null, texto: r.geracao ? r.geracao.modo : 'n/d', recomendacoes: linhas, qualidadeDados: r.qualidadeDados } };
return [mqttMsg, dbg];

